"""Snapshot/verify that only comments+docstrings changed in Python files."""
import ast, hashlib, json, sys

def stripped_hash(path):
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            body = node.body
            if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):
                if len(body) == 1:
                    body[0] = ast.Pass()
                else:
                    del body[0]
    return hashlib.sha256(ast.dump(tree).encode()).hexdigest()

cmd, snap_file = sys.argv[1], sys.argv[2]
files = sys.argv[3:]
if cmd == "snapshot":
    json.dump({f: stripped_hash(f) for f in files}, open(snap_file, "w"))
    print(f"snapshotted {len(files)} files")
else:
    snap = json.load(open(snap_file))
    bad = [f for f, h in snap.items() if stripped_hash(f) != h]
    if bad:
        print("CODE CHANGED (not just prose):"); [print(" ", f) for f in bad]; sys.exit(1)
